package com.lifeos.goals;import com.lifeos.shared.AuditableEntity;import com.lifeos.users.User;import jakarta.persistence.*;import java.time.*;@Entity @Table(name="goals")public class Goal extends AuditableEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,length=200)private String title;@Column(columnDefinition="text")private String description;private LocalDate targetDate;@Enumerated(EnumType.STRING)@Column(nullable=false)private GoalStatus status=GoalStatus.ACTIVE;@Column(nullable=false)private Integer progress=0;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id",nullable=false)private User user;public Long getId(){return id;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public LocalDate getTargetDate(){return targetDate;}public void setTargetDate(LocalDate v){targetDate=v;}public GoalStatus getStatus(){return status;}public void setStatus(GoalStatus v){status=v;}public Integer getProgress(){return progress;}public void setProgress(Integer v){progress=v;}public void setUser(User v){user=v;}}
